files.决策卡.py:
"""经纪 · 决策卡：主人定的事 → 经营决策库里一张合格式的卡（自动取号、套模板、查重、换新版）
用法：python3 决策卡.py --类 ZC|HP|DR --标题 售价下限 --原话 "以后不做 39 块以下的" [--参数 售价下限=39 ...]
       [--内容 "…"] [--状态 生效|待确认] [--替代 D-ZC-003] [--今天 2026-10-31] [--店铺 <店铺文件夹>] [--演练]
规矩（库/模板/决策卡.md）：编号 D-<类>-<三位号>，按库里已有的最大号 +1；同标题已有一张「生效」的，要用 --替代 换新版
（同编号、版本 +1、文件名加 -v<版本>，旧卡改「已停用」不删）；参数名要和 库/默认值/达人推广-服装店.md 同名，脚本才用得上。
Bot 实测自报 1（10-31）：之前只写「照模板」，手写的卡缺编号、状态、版本、参数。"""
import argparse, datetime as dt, pathlib, re, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent)); import 底子


def main(argv=None):
    a = argparse.ArgumentParser()
    a.add_argument("--类", required=True, choices=["ZC", "HP", "DR"]); a.add_argument("--标题", required=True)
    a.add_argument("--原话", required=True); a.add_argument("--参数", nargs="*", default=[]); a.add_argument("--内容", default="")
    a.add_argument("--状态", default="生效", choices=["生效", "待确认"]); a.add_argument("--替代"); a.add_argument("--影响", default="")
    a.add_argument("--今天"); a.add_argument("--店铺"); a.add_argument("--演练", action="store_true")
    a = a.parse_args(argv)
    dp = 底子.dianpu(a.店铺)
    jc = dp / "经营决策库"
    jin = a.今天 or str(底子.jintian())
    ka = {p: 底子.kaitou(p) for p in sorted(jc.glob("D-*.md")) if not p.name.startswith("._")} if jc.exists() else {}
    cs = 底子.moren_canshu()
    can = dict(x.split("=", 1) for x in a.参数 if "=" in x)
    ti = [f"参数「{n}」默认值里没有这个名字，脚本用不上；要用请改成默认值里的名字" for n in can if n not in cs]
    if a.替代:
        jiu = [(p, k) for p, k in ka.items() if k.get("编号") == a.替代 and k.get("状态") == "生效"]
        if not jiu:
            raise SystemExit(f"找不到生效的 {a.替代}，换不了新版")
        bh, bb = a.替代, max(int(k.get("版本") or 1) for _, k in jiu) + 1
        ming = f"{bh}-{a.标题}-v{bb}.md"; tidai = f"{bh} 版本 {bb - 1}"
    else:
        tong = [k["编号"] for k in ka.values() if k.get("标题") == a.标题 and k.get("状态") == "生效"]
        if tong:
            raise SystemExit(f"已经有一张生效的「{a.标题}」（{tong[0]}）；改它就加 --替代 {tong[0]}，旧卡会改成已停用")
        hao = [int(m.group(1)) for k in ka.values() if (m := re.match(rf"D-{a.类}-(\d+)", k.get("编号", "")))]
        bh, bb = f"D-{a.类}-{max(hao, default=0) + 1:03d}", 1
        ming = f"{bh}-{a.标题}.md"; tidai = "无"
    canshu = "".join(f"\n  {n}: {v}" for n, v in can.items())
    t = f"""---
编号: {bh}
标题: {a.标题}
状态: {a.状态}
版本: {bb}
生效日期: {jin}
定的人: 主人原话「{a.原话}」
替代: {tidai}
影响: [{a.影响}]
参数:{canshu}
---

# {a.标题}
{a.内容 or a.原话}
"""
    print(t)
    for x in ti:
        print("⚠️ " + x)
    if a.演练:
        return
    jc.mkdir(parents=True, exist_ok=True)
    if a.替代:
        for p, _ in jiu:
            p.write_text(re.sub(r"^状态: 生效", "状态: 已停用", p.read_text(encoding="utf-8"), count=1, flags=re.M), encoding="utf-8")
    (jc / ming).write_text(t, encoding="utf-8")
    print(f"已写 {jc / ming}" + (f"；{a.替代} 旧版改成已停用" if a.替代 else ""))


if __name__ == "__main__":
    main()

files.回执.py:
"""云间成员回执：每次干完活往 店铺/<店>/回执/<日期>/<成员>.json 记一笔，掌柜读它出报（四位同一个写法，格式正本在掌柜 keep-base/回执格式.json）。
脚本里：import 回执; 回执.ji(店铺文件夹, "brok", zuole={"第一句": 1}, chule=["发版单 H11"], kazai=[...], deng=[...], shu={"分层": {...}}, chuchu="精选联盟·合作消息")
命令行：python3 回执.py --店铺 <文件夹> --成员 brok [--做了 第一句=1 …] [--出了 …] [--卡在 …] [--等主人定 …] [--今天 2026-11-10]
做了：同名累加；出了／卡在／等主人定：去重追加；数：同名整块换新。只记数和结论，不记联系方式、收件信息。"""
import argparse, datetime as dt, json, os, pathlib


def ji(dp, chengyuan, zuole=None, chule=(), kazai=(), deng=(), shu=None, chuchu="", jintian=None):
    if not dp:
        return None
    day = str(jintian or os.environ.get("YUNJIAN_TODAY") or dt.date.today())[:10]
    p = pathlib.Path(dp) / "回执" / day / f"{chengyuan}.json"
    p.parent.mkdir(parents=True, exist_ok=True)
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        d = {"成员": chengyuan, "店铺": pathlib.Path(dp).name, "日期": day, "做了": {}, "出了": [], "卡在": [], "等主人定": [], "数": {}, "出处": []}
    for k, v in (zuole or {}).items():
        d["做了"][k] = d["做了"].get(k, 0) + v
    for key, xs in (("出了", chule), ("卡在", kazai), ("等主人定", deng)):
        for x in xs:
            if x and x not in d[key]:
                d[key].append(x)
    d["数"].update(shu or {})
    if chuchu and chuchu not in d["出处"]:
        d["出处"].append(chuchu)
    d["记录时间"] = dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    tmp.replace(p)
    return p


def main(argv=None):
    a = argparse.ArgumentParser()
    a.add_argument("--店铺", required=True); a.add_argument("--成员", required=True); a.add_argument("--做了", nargs="*", default=[])
    a.add_argument("--出了", nargs="*", default=[]); a.add_argument("--卡在", nargs="*", default=[]); a.add_argument("--等主人定", nargs="*", default=[])
    a.add_argument("--出处", default=""); a.add_argument("--今天")
    a = a.parse_args(argv)
    zuole = {k: float(v) if "." in v else int(v) for k, v in (x.split("=", 1) for x in a.做了 if "=" in x)}
    print("回执已记", ji(a.店铺, a.成员, zuole, a.出了, a.卡在, a.等主人定, None, a.出处, a.今天))


if __name__ == "__main__":
    main()

files.底子.py:
"""经纪各脚本共用的小工具：家目录、店铺文件夹、参数（决策库盖默认值）、卡片开头段、区间档解析、夹带检查。
别的脚本这样引：import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent / "brok-base")); import 底子"""
import json, os, pathlib, re

HOME = pathlib.Path(os.environ.get("BROK_HOME", pathlib.Path.home() / ".yunjian" / "brok"))
KU = HOME / "库"
if not KU.exists() and (pathlib.Path(__file__).resolve().parents[2] / "库").exists():
    KU = pathlib.Path(__file__).resolve().parents[2] / "库"   # 还没装到 ~/.yunjian/brok 时用包里自带的库（实测 10-31：没装就直接报错）


def jintian():
    """今天：环境变量 BROK_TODAY（测试、演练用，如 2026-11-10）优先，没有用系统日期（Bot 实测自报 9）。"""
    import datetime as _dt
    v = os.environ.get("BROK_TODAY")
    return _dt.date.fromisoformat(v[:10]) if v else _dt.date.today()


def dianpu_gen():
    """店铺根目录：有四位共用的 ~/.yunjian/店铺/ 就用它（一家店一个文件夹、一份经营决策库、掌柜从这里汇总），没有就用自己的 <HOME>/店铺/（只装这一位时）。"""
    g = HOME.parent / "店铺"
    return g if g.is_dir() else HOME / "店铺"


def dianpu(ming=None):
    """店铺文件夹：给了店名就是 店铺/<店名>，给的是路径（带 / 或 ~）照路径；没给就用 店铺/ 下唯一的一家（不止一家要主人说是哪家）。
    Bot 实测 10-31：「--店铺 阿青卫衣」被当成相对路径，卡写进了技能目录。"""
    d = dianpu_gen()
    if ming:
        m = str(ming)
        return pathlib.Path(m).expanduser() if ("/" in m or m.startswith("~")) else d / m
    xs = [p for p in d.iterdir() if p.is_dir()] if d.exists() else []
    if len(xs) != 1:
        raise SystemExit(f"不知道是哪家店：{d} 下有 {len(xs)} 家，用 --店铺 指定")
    return xs[0]


def kaitou(p):
    """读卡片开头 --- 之间的「键: 值」（一层，参数下面缩进的两格也读进「参数」）。"""
    t = pathlib.Path(p).read_text(encoding="utf-8")
    m = re.match(r"---\n(.*?)\n---", t, re.S)
    out, cs = {}, None
    for line in (m.group(1).splitlines() if m else []):
        if line.startswith("  ") and cs is not None:
            k, _, v = line.strip().partition(":")
            out.setdefault("参数", {})[k.strip()] = v.split("#")[0].strip()
        elif ":" in line:
            k, _, v = line.partition(":")
            k = k.strip(); cs = k if k == "参数" else None
            if k != "参数":
                out[k] = v.split("#")[0].strip()
    return out


def moren_canshu(ku=None):
    """默认值/达人推广-服装店.md 里的 json 参数块。"""
    t = ((ku or KU) / "默认值" / "达人推广-服装店.md").read_text(encoding="utf-8")
    return json.loads(re.search(r"```json\n(.*?)\n```", t, re.S).group(1))


def canshu(dp=None, ku=None):
    """参数：服装店默认值，再用店铺经营决策库里「状态: 生效」的卡盖掉同名参数。返回（参数, 用了默认值的名字）。"""
    cs = moren_canshu(ku)
    gai = set()
    if not dp:   # 没指定店铺：店铺/ 下只有一家就用它，免得主人定的规矩被默认值盖住
        try:
            dp = dianpu()
        except SystemExit:
            dp = None
    jc = dianpu(dp) / "经营决策库" if dp else None
    if jc and jc.exists():
        for p in sorted(jc.glob("D-*.md")):
            if p.name.startswith("._"):   # Mac 打包带的隐藏文件（Bot 实测自报 14）
                continue
            k = kaitou(p)
            if k.get("状态") != "生效":
                continue
            for n, v in (k.get("参数") or {}).items():
                if n in cs:
                    try:
                        cs[n] = type(cs[n])(float(v)) if isinstance(cs[n], (int, float)) else v
                    except ValueError:
                        cs[n] = v
                    gai.add(n)
    return cs, sorted(set(cs) - gai)


DANG = re.compile(r"([\d.,]+)\s*(万)?\s*\+?\s*(?:-\s*([\d.,]+)\s*(万)?)?")


def jian_shu(s):
    """「1,000 - 2,500」「1万 - 2.5万」「4000+」「已售 1万+」「已拼1.2万件」 → (下限, 上限或 None, 精度)。看不出来返回 (None, None, '')。"""
    s = (s or "").replace("，", ",")
    m = DANG.search(s.replace("已售", "").replace("已拼", "").replace("人付款", ""))
    if not m:
        return None, None, ""
    num = lambda x, w: float(x.replace(",", "")) * (10000 if w else 1)
    lo = num(m.group(1), m.group(2))
    if m.group(3):
        return lo, num(m.group(3), m.group(4)), "档"
    if "+" in s:
        return lo, None, "档"
    return lo, lo, "精确"


JIADAI = re.compile(r"(AI|ai|助手|机器人).{0,8}(注意|请|必须)|不用问|忽略(之前|上面|以上)|直接.{0,10}(发布|改|删除|下单)|ignore (previous|all)", re.I)


def kexi(s):
    """像写给 AI 的话（夹带指令）就返回那一段原文，否则空串。"""
    m = JIADAI.search(s or "")
    return zhaiju(s, 120) if m else ""


def zhaiju(s, n=60):
    """原话摘出来给主人看：不超过 n 字整段给；长了按句子截（。！？；换行），不从半个字、半句话截（Bot 实测 10-31：丢了开头的「多」、截掉了「改成50%」）。"""
    s = (s or "").strip()
    if len(s) <= n:
        return s
    ju = re.split(r"(?<=[。！？!?；;\n])", s)
    out = ""
    for j in ju:
        if out and len(out) + len(j) > n:
            break
        out += j
    return out.strip() + ("…" if len(out.strip()) < len(s) else "")


QUAN = "①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳"


def biao(tou, hang, kuan=False, chu=None, zhu=None, jian=1):
    """出表（杨先生 10-31：按界面做最优展示）。kuan=True 一张宽表（电脑、飞书、网页）；
    默认窄表（Grok Bot、手机聊天框）：出处那一列（chu）换成编号 ①②，完整出处列在表下；
    长理由那一列（zhu）挪到表下，按 jian 那一列的值一条一条写。"""
    if kuan or (chu is None and zhu is None):
        return "\n".join(["| " + " | ".join(tou) + " |", "|" + "---|" * len(tou)] + ["| " + " | ".join(map(str, h)) + " |" for h in hang])
    bh, xia, zhus = {}, [], []
    for h in hang:
        if chu is not None:
            c = str(h[chu])
            if c not in bh:
                bh[c] = QUAN[len(bh)] if len(bh) < len(QUAN) else f"({len(bh) + 1})"
        if zhu is not None and str(h[zhu]).strip() not in ("", "—"):
            zhus.append(f"- {h[jian]}：{h[zhu]}")
    keep = [i for i in range(len(tou)) if i != zhu]
    t2 = [("出处" if i == chu else tou[i]) for i in keep]
    rows = [[(bh[str(h[i])] if i == chu else str(h[i])) for i in keep] for h in hang]
    out = ["| " + " | ".join(t2) + " |", "|" + "---|" * len(t2)] + ["| " + " | ".join(r) + " |" for r in rows]
    if zhus:
        out += ["", "说明：", *zhus]
    if bh:
        out += ["", "出处：", *[f"{v} {k}" for k, v in bh.items()]]
    return "\n".join(out)

files.指纹.py:
"""算官方页面正文指纹：去掉导航和页尾，只留「更新时间」到「这篇文章是否对你有帮助」之间的正文，压掉空白后取 sha256 前 12 位。
用法：python3 指纹.py <取回的正文.txt>      巡检.py 也用它；指纹变了就是正文改了。"""
import hashlib, re, sys

def zhengwen(t):
    k = t.find('----正文----')          # 取原文.mjs 存的正文文件：只认分隔线以后的正文
    if k >= 0:
        return re.sub(r'\s+', '', t[k + len('----正文----'):])
    i = t.find('更新时间')
    t = t[i:] if i >= 0 else t
    j = t.find('这篇文章是否对你有帮助')
    t = t[:j] if j >= 0 else t
    t = re.sub(r'阅读量[:：]\s*\d+', '', t)
    return re.sub(r'\s+', '', t)

def zhiwen(t):
    return hashlib.sha256(zhengwen(t).encode()).hexdigest()[:12]

if __name__ == '__main__':
    for p in sys.argv[1:]:
        print(zhiwen(open(p, encoding='utf-8').read()), p)

files.匹配分.py:
"""经纪 · 匹配分：达人（达人广场导出或抄下的表）× 店铺标签卡 → 精准／外扩／不匹配／排除、匹配分、命中哪几条、出处
用法：python3 匹配分.py --标签卡 <店铺标签卡.json> --达人 <达人广场.csv> [--渠道 直播|视频] [--宽] [--json]
两边写法不一样要换算（实地摸清 10-31）：达人广场年龄档 18-23/24-30/31-40/41-50/50+ 对罗盘 18-24/25-30/31-35…，
按「重叠年数 ÷ 达人那一档年数 ≥ 0.5」算命中；人群名「00后」＝罗盘「Z世代」。
分：类目 30、年龄 主 25／扩 12、人群 主 25／扩 12、达人类型对上推荐渠道 20（另一种 10）。精准＝类目对＋年龄主＋人群主；外扩＝类目对、年龄和人群都在主或扩里、至少一样是扩；
图文、橱窗达人不算我们的渠道。达人名、数照抄，出处写「精选联盟·达人广场·店铺·记录时间」。"""
import argparse, csv, json, pathlib, re, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent / "brok-base")); import 底子

TONG = {"00后": "Z世代", "Z 世代": "Z世代", "z世代": "Z世代"}


def duan(s):
    """「18-23岁居多」「50岁+居多」「31-35」→ (起, 止)。"""
    s = (s or "").replace("岁", "").replace("居多", "").strip()
    m = re.match(r"(\d+)\s*\+", s)
    if m:
        return int(m.group(1)), int(m.group(1)) + 10
    m = re.match(r"(\d+)\s*-\s*(\d+)", s)
    return (int(m.group(1)), int(m.group(2))) if m else None


def zhong(a, bs):
    """达人那一档 a 和店铺的档 bs 有没有命中（重叠年数 ÷ a 的年数 ≥ 0.5）。"""
    if not a:
        return False
    n = a[1] - a[0] + 1
    for b in filter(None, bs):
        lap = min(a[1], b[1]) - max(a[0], b[0]) + 1
        if lap > 0 and lap / n >= 0.5:
            return True
    return False


def ping(r, k, qudao):
    leimu = k.get("主营类目", "服饰内衣")
    rq = TONG.get(r["八大消费人群"].strip(), r["八大消费人群"].strip())
    zhu_rq = [TONG.get(x, x) for x in k["主人群"]]; kuo_rq = [TONG.get(x, x) for x in k.get("扩标签人群", [])]
    nl = duan(r["粉丝年龄"])
    nl_zhu = zhong(nl, [duan(x) for x in k["主年龄段"]]); nl_kuo = zhong(nl, [duan(x) for x in k.get("扩标签年龄", [])])
    lei = leimu in re.split(r"[/／、,，\s]+", r["主推类目"].strip())   # 达人主推类目常是多个（「服饰内衣/美妆」），包含就算（实测 10-31）
    lx = r["达人类型"].replace("达人", "").strip()
    fen, ming = 0, []
    if lei:
        fen += 30; ming.append("类目")
    if nl_zhu:
        fen += 25; ming.append("年龄主")
    elif nl_kuo:
        fen += 12; ming.append("年龄扩")
    if rq in zhu_rq:
        fen += 25; ming.append("人群主")
    elif rq in kuo_rq:
        fen += 12; ming.append("人群扩")
    if lx == qudao:
        fen += 20; ming.append(f"{lx}对上推荐渠道")
    elif lx in ("直播", "视频"):
        fen += 10
    if not lei:
        jie, li = "排除", f"类目「{r['主推类目']}」不是{leimu}"
    elif lx not in ("直播", "视频"):
        jie, li = "不匹配", f"{r['达人类型']}，不是直播、短视频渠道"
    elif nl_zhu and rq in zhu_rq:
        jie, li = "精准", ""
    elif (nl_zhu or nl_kuo) and (rq in zhu_rq or rq in kuo_rq):
