    if d.get("佣金") is not None and abs(float(d["佣金"]) - float(r.get("佣金", -1))) > 1e-6:
        cuo.append(f"佣金：谈定 {d['佣金']:.0%}，后台 {float(r.get('佣金', 0)):.0%}" + ("（降佣次日 0 点才生效，明天再回读一次）" if d.get("降佣") else ""))
    if d.get("链接类型") == "渠道品":
        if str(r.get("渠道品绑定UID")) != str(d.get("UID")):
