    n = {c: sum(1 for v in out.values() if v["层"] == c) for c in ("核心", "成长", "新", "沉睡")}
    print(f"{len(out)} 位达人：核心 {n['核心']}、成长 {n['成长']}、新 {n['新']}、沉睡 {n['沉睡']}" + ("" if lr else "（没给算盘利润回执（--利润），「利润前 20%」这条没算）") + ("；阈值按默认值" if "核心_近天数" in mo else ""))
    try:
